import{_ as e,o as a,c as n,am as o}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"Window电脑安装运行docker服务","description":"","frontmatter":{"title":"Window电脑安装运行docker服务","excerpt":"摘要","date":"2026-08-03 23:34:30","updated":"2026-08-03 23:34:30"},"headers":[],"relativePath":"部署&工具/Java 知识体系-容器部署/Docker 基础/Docker的下载和安装/Window电脑安装运行docker服务.md","filePath":"部署&工具/Java 知识体系-容器部署/Docker 基础/Docker的下载和安装/Window电脑安装运行docker服务.md","lastUpdated":null}'),t={name:"部署&工具/Java 知识体系-容器部署/Docker 基础/Docker的下载和安装/Window电脑安装运行docker服务.md"};function p(l,s,i,r,c,d){return a(),n("div",null,[...s[0]||(s[0]=[o(`<p>Windows 上推荐使用 <strong>Docker Desktop</strong> 安装运行 Docker（自带 Docker CLI、Docker Compose、图形化界面）</p><h3 id="_1、检查系统要求" tabindex="-1">1、检查系统要求 <a class="header-anchor" href="#_1、检查系统要求" aria-label="Permalink to &quot;1、检查系统要求&quot;">​</a></h3><ul><li>Windows 10 64 位（版本 22H2，build 19045 或更高）/ Windows 11 64 位（23H2 或更高）</li><li>开启 BIOS 虚拟化（Intel VT-x 或 AMD-V），处理器需支持 SLAT</li><li>内存 <strong>8GB 以上</strong>（官方硬性要求）</li><li>WSL 版本 2.1.5 或更高（需启用 WSL 2 功能）</li></ul><p>可以在任务管理器 → 性能 → CPU 中查看&quot;虚拟化&quot;是否已启用</p><h3 id="_2、安装并启用-wsl-2" tabindex="-1">2、安装并启用 WSL 2 <a class="header-anchor" href="#_2、安装并启用-wsl-2" aria-label="Permalink to &quot;2、安装并启用 WSL 2&quot;">​</a></h3><p>以<strong>管理员身份</strong>打开 PowerShell，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 安装 WSL 2 及默认的 Linux 发行版（会自动重启）</span></span>
<span class="line"><span>wsl --install</span></span></code></pre></div><p>安装完成后重启电脑，然后设置默认版本为 WSL 2：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wsl --set-default-version 2</span></span></code></pre></div><p>验证是否安装成功：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wsl --version</span></span>
<span class="line"><span>wsl --status</span></span>
<span class="line"><span>wsl -l -v</span></span></code></pre></div><blockquote><p>如果 <code>wsl --version</code> 没有输出版本信息，说明是系统自带的旧版 WSL，执行 <code>wsl --update</code> 升级（需要管理员权限）</p></blockquote><h3 id="_3、下载安装-docker-desktop" tabindex="-1">3、下载安装 Docker Desktop <a class="header-anchor" href="#_3、下载安装-docker-desktop" aria-label="Permalink to &quot;3、下载安装 Docker Desktop&quot;">​</a></h3><ul><li>官网下载地址： <a href="https://www.docker.com/products/docker-desktop/" target="_blank" rel="noreferrer">https://www.docker.com/products/docker-desktop/</a></li><li>选择 <strong>Windows</strong> 版本下载（提供 AMD64 / ARM64 两种安装包）</li></ul><blockquote><p><strong>AMD64 与 ARM64 怎么选</strong>：AMD64 对应 Intel 酷睿 / AMD 锐龙等传统 x86 处理器（绝大多数电脑）；ARM64 对应高通骁龙 X 系列等 ARM 处理器（2024 年后的 Copilot+ PC 等）。在 PowerShell 执行 <code>echo $env:PROCESSOR_ARCHITECTURE</code>，输出 <code>AMD64</code> 就下载 AMD64 版，输出 <code>ARM64</code> 就下载 ARM64 版，选错会导致无法运行</p></blockquote><ul><li>双击安装包，安装时在 Configuration 页面勾选 <strong>Use WSL 2 instead of Hyper-V</strong>（推荐，系统只支持一种后端时会自动选中）</li></ul><p>安装完成后，搜索并启动 <strong>Docker Desktop</strong>（不会自动启动）。首次启动需要阅读并 <strong>Accept</strong> 订阅服务协议，之后等待右下角鲸鱼图标变为稳定状态（Running）即可</p><h3 id="_4、验证安装" tabindex="-1">4、验证安装 <a class="header-anchor" href="#_4、验证安装" aria-label="Permalink to &quot;4、验证安装&quot;">​</a></h3><p>打开 PowerShell 或 CMD，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker --version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker compose version</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 拉取并运行一个测试镜像</span></span>
<span class="line"><span>docker run hello-world</span></span></code></pre></div><p>看到 <code>Hello from Docker!</code> 输出即表示安装成功</p><h3 id="_5、配置镜像加速" tabindex="-1">5、配置镜像加速 <a class="header-anchor" href="#_5、配置镜像加速" aria-label="Permalink to &quot;5、配置镜像加速&quot;">​</a></h3><p>打开 Docker Desktop → <strong>Settings</strong> → <strong>Docker Engine</strong>，在 JSON 配置中添加 <code>registry-mirrors</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;registry-mirrors&quot;: [</span></span>
<span class="line"><span>    &quot;https://docker.mirrors.sjtug.sjtu.edu.cn&quot;,</span></span>
<span class="line"><span>    &quot;https://docker.m.daocloud.io&quot;</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>点击 <strong>Apply &amp; restart</strong> 重启生效，验证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker info</span></span></code></pre></div><p>查看 <code>Registry Mirrors</code> 一栏是否出现配置的地址</p><blockquote><p>镜像源不建议配置太多，保留 1-2 个稳定的即可；国内常用的加速源可参考 <a href="/java-site/部署%26工具/Java 知识体系-容器部署/Docker 基础/Docker的下载和安装/Linux系统安装 Docker.html">Linux系统安装 Docker操作</a> 中的汇总</p></blockquote><h3 id="_6、常见问题" tabindex="-1">6、常见问题 <a class="header-anchor" href="#_6、常见问题" aria-label="Permalink to &quot;6、常见问题&quot;">​</a></h3><p><strong>问题 1：Docker Desktop requires a newer WSL kernel version</strong></p><p>WSL 内核版本过旧，先执行 <code>wsl --update</code> 升级；若系统为旧版 WSL（非 Store 版本），可下载安装 WSL2 Linux 内核更新包（MSI）： <a href="https://learn.microsoft.com/zh-cn/windows/wsl/install-manual#step-4---download-the-linux-kernel-update-package" target="_blank" rel="noreferrer">https://learn.microsoft.com/zh-cn/windows/wsl/install-manual#step-4---download-the-linux-kernel-update-package</a></p><p>升级完成后重启 Docker Desktop</p><p><strong>问题 2：启动报错 WSL 2 installation is incomplete</strong></p><p>以管理员身份重新执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wsl --update</span></span>
<span class="line"><span>wsl --set-default-version 2</span></span></code></pre></div><p><strong>问题 3：拉取镜像超时</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker: Error response from daemon: Get &quot;https://registry-1.docker.io/v2/&quot;: net/http: request canceled while waiting for connection</span></span></code></pre></div><p>按第 5 步配置镜像加速源后重启 Docker Desktop</p>`,38)])])}const k=e(t,[["render",p]]);export{u as __pageData,k as default};
